//#region src/utils/platformEnvironment.ts
function detectPlatform() {
	if (typeof window === "undefined") return {
		isAndroid: false,
		isAndroidWebView: false,
		isCapacitor: false,
		isCordova: false,
		isPWA: false,
		isWebPreview: true,
		hasNativeBrowserBridge: false,
		platformName: "Server / Node Environment",
		supportsPersistentStorage: false,
		supportsFullCookies: false,
		engineDescription: "Server Side"
	};
	const ua = navigator.userAgent || "";
	const isAndroid = /Android/i.test(ua);
	const isAndroidWebView = Boolean(window.AndroidBridge) || Boolean(window.alyaNativeBrowser) || Boolean(window.Android) || /wv|WebView|Version\/[\d\.]+ Chrome/i.test(ua);
	const isCapacitor = Boolean(window.Capacitor);
	const isCordova = Boolean(window.cordova);
	const isPWA = window.matchMedia("(display-mode: standalone)").matches || window.navigator.standalone === true;
	const hasNativeBrowserBridge = Boolean(window.AndroidBridge?.openUrl) || Boolean(window.alyaNativeBrowser?.openTab) || Boolean(window.Capacitor?.Plugins?.Browser?.open);
	let platformName = "Web Preview Engine";
	let engineDescription = "Standard Web Sandbox (Iframe + Direct Navigation)";
	if (isCapacitor) {
		platformName = "Capacitor Android/iOS Container";
		engineDescription = "Capacitor Native InAppBrowser / Chrome Custom Tabs";
	} else if (isCordova) {
		platformName = "Apache Cordova Container";
		engineDescription = "Cordova InAppBrowser System Engine";
	} else if (isAndroidWebView) {
		platformName = "Android Native WebView";
		engineDescription = "Android WebKit System Engine";
	} else if (isPWA) {
		platformName = "Progressive Web App (PWA)";
		engineDescription = "Standalone PWA Engine";
	}
	const isWebPreview = !isCapacitor && !isCordova && !isAndroidWebView;
	return {
		isAndroid,
		isAndroidWebView,
		isCapacitor,
		isCordova,
		isPWA,
		isWebPreview,
		hasNativeBrowserBridge,
		platformName,
		supportsPersistentStorage: typeof localStorage !== "undefined",
		supportsFullCookies: !isWebPreview || isPWA || isAndroidWebView,
		engineDescription
	};
}
/**
* Open requested URL in native browser container or new browser context
*/
function openExternalBrowser(url) {
	if (!url || typeof window === "undefined") return false;
	let targetUrl = url.trim();
	if (!/^https?:\/\//i.test(targetUrl)) targetUrl = `https://${targetUrl}`;
	try {
		if (window.AndroidBridge?.openUrl) {
			window.AndroidBridge.openUrl(targetUrl);
			return true;
		}
		if (window.Android?.openUrl) {
			window.Android.openUrl(targetUrl);
			return true;
		}
		if (window.alyaNativeBrowser?.openTab) {
			window.alyaNativeBrowser.openTab(targetUrl);
			return true;
		}
		if (window.Capacitor?.Plugins?.Browser?.open) {
			window.Capacitor.Plugins.Browser.open({ url: targetUrl });
			return true;
		}
		if (window.cordova?.InAppBrowser?.open) {
			window.cordova.InAppBrowser.open(targetUrl, "_system");
			return true;
		}
		const win = window.open(targetUrl, "_blank", "noopener,noreferrer");
		if (win && !win.closed && typeof win.closed !== "undefined") {
			try {
				win.focus();
			} catch (_) {}
			return true;
		}
	} catch (err) {
		console.warn("Direct browser launch failed:", err);
	}
	try {
		const link = document.createElement("a");
		link.href = targetUrl;
		link.target = "_blank";
		link.rel = "noopener noreferrer";
		document.body.appendChild(link);
		link.click();
		setTimeout(() => {
			try {
				if (link.parentNode) document.body.removeChild(link);
			} catch (_) {}
		}, 150);
		return true;
	} catch (_) {}
	return false;
}
/**
* Parse YouTube URLs and extract video ID for official player embed
*/
function parseYouTubeVideoId(url) {
	if (!url) return null;
	const clean = url.trim();
	const watchMatch = clean.match(/(?:youtube\.com\/(?:watch\?.*v=|embed\/|v\/|shorts\/)|youtu\.be\/)([a-zA-Z0-9_-]{11})/i);
	if (watchMatch && watchMatch[1]) return watchMatch[1];
	const shortsMatch = clean.match(/youtube\.com\/shorts\/([a-zA-Z0-9_-]{11})/i);
	if (shortsMatch && shortsMatch[1]) return shortsMatch[1];
	return null;
}
/**
* Generate official compliant YouTube player embed URL
*/
function getYouTubeEmbedUrl(url) {
	const videoId = parseYouTubeVideoId(url);
	if (!videoId) return null;
	const origin = typeof window !== "undefined" ? window.location.origin : "https://example.com";
	return `https://www.youtube-nocookie.com/embed/${videoId}?autoplay=1&enablejsapi=1&origin=${encodeURIComponent(origin)}&rel=0`;
}
/**
* Check if domain is known to strictly prohibit third-party framing
*/
var KNOWN_XFO_RESTRICTED_DOMAINS = [
	"google.com",
	"accounts.google.com",
	"github.com",
	"youtube.com",
	"youtu.be",
	"twitter.com",
	"x.com",
	"facebook.com",
	"instagram.com",
	"linkedin.com",
	"reddit.com",
	"netflix.com",
	"amazon.com",
	"apple.com",
	"microsoft.com",
	"login.live.com",
	"developer.mozilla.org",
	"stackoverflow.com"
];
function isDomainRestricted(url) {
	if (!url || url.startsWith("alya://") || url.startsWith("search://")) return false;
	if (parseYouTubeVideoId(url)) return false;
	try {
		const host = new URL(url.startsWith("http") ? url : `https://${url}`).hostname.toLowerCase();
		return KNOWN_XFO_RESTRICTED_DOMAINS.some((d) => host === d || host.endsWith(`.${d}`));
	} catch {
		return false;
	}
}
