  "topic": "${topic}",
  "slides": [
    {
      "title": "Slide Title",
      "subtitle": "Short subtitle or context",
      "bullets": [
        "Key point 1 with actionable insight",
        "Key point 2 with clear explanation",
        "Key point 3 with impactful conclusion"
      ]
    }
  ]
